export const PORTRAIT_EXAMPLE_SIZE = 192

// 192x192 center-cropped RGB bytes derived from /images.jpeg
const PORTRAIT_EXAMPLE_RGB_BASE64 =
  ''

let cachedRgba: Uint8ClampedArray | null = null

function decodeBase64ToBytes(encoded: string): Uint8Array {
  if (typeof globalThis.atob === "function") {
    const bin = globalThis.atob(encoded)
    const out = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
    return out
  }
  const maybeBuffer = (globalThis as { Buffer?: { from(data: string, enc: string): Uint8Array } }).Buffer
  if (maybeBuffer) {
    return maybeBuffer.from(encoded, "base64")
  }
  throw new Error("当前运行环境不支持内置人像示例解码。")
}

/**
 * Synchronously decodes the bundled 192x192 portrait photograph into an RGBA pixel buffer
 * shared across WireCraft, Compass, and Carving portrait examples.
 */
export function getPortraitExampleRgba(): Uint8ClampedArray {
  if (cachedRgba) return cachedRgba
  const rgb = decodeBase64ToBytes(PORTRAIT_EXAMPLE_RGB_BASE64)
  const pixels = PORTRAIT_EXAMPLE_SIZE * PORTRAIT_EXAMPLE_SIZE
  const rgba = new Uint8ClampedArray(pixels * 4)
  for (let i = 0, s = 0, d = 0; i < pixels; i++, s += 3, d += 4) {
    rgba[d] = rgb[s]
    rgba[d + 1] = rgb[s + 1]
    rgba[d + 2] = rgb[s + 2]
    rgba[d + 3] = 255
  }
  cachedRgba = rgba
  return rgba
}
